  "path": "supabase/functions/user-stats/index.ts",
  "contents": "import "@supabase/functions-js/edge-runtime.d.ts";
import { withSupabase } from "npm:@supabase/server";

/**
 * Return stats for the signed-in caller, or for a user requested by the
 * trusted billing service. The user client is deliberately used for the user
 * path so that the database RLS policy remains the final authorization check.
 */
export default {
  fetch: withSupabase({ auth: ["user", "secret"] }, async (req, ctx) => {
    if (req.method !== "POST") {
      return Response.json({ error: "method_not_allowed" }, { status: 405 });
    }

    let body: { user_id?: unknown };
    try {
      body = await req.json();
    } catch {
      return Response.json({ error: "invalid_json" }, { status: 400 });
    }

    let userId: string;
    let client;

    if (ctx.authMode === "user") {
      // Never accept user_id from a user-authenticated request: doing so would
      // turn this endpoint into an IDOR even if the RLS policy changed later.
      userId = ctx.userClaims?.sub ?? "";
      client = ctx.supabase;
    } else {
      if (typeof body.user_id !== "string") {
        return Response.json({ error: "user_id_required" }, { status: 400 });
      }
      userId = body.user_id;
      client = ctx.supabaseAdmin;
    }

    // Keep malformed identifiers from reaching the database and make the
    // service endpoint's input contract explicit.
    if (
      !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
        userId,
      )
    ) {
      return Response.json({ error: "invalid_user_id" }, { status: 400 });
    }

    const { data, error } = await client
      .from("user_stats")
      .select("user_id, metric, value")
      .eq("user_id", userId)
      .order("metric");

    if (error) {
      console.error("user_stats query failed", error.message);
      return Response.json({ error: "stats_unavailable" }, { status: 500 });
    }

    return Response.json(data);
  }),
};
"
}

