import { withSupabase } from "npm:@supabase/server";

/**
 * Return stats for the signed-in caller, or for a user requested by the
 * trusted billing service. The user client is deliberately used for the user
 * path so that the database RLS policy remains the final authorization check.
 */
Deno.serve(
  fetch: withSupabase({ auth: ["user", "secret"] }, async (req, ctx) => {
    if (req.method !== "POST") {
      return Response.json({ error: "method_not_allowed" }, { status: 405 });
    }

    return Response.json(data);
